CREATE TABLE category (id BIGSERIAL PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, description TEXT, sort_order INTEGER NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL DEFAULT 'ENABLED', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE topic (id BIGSERIAL PRIMARY KEY, category_id BIGINT NOT NULL REFERENCES category(id), code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, description TEXT, star_level SMALLINT NOT NULL DEFAULT 3 CHECK (star_level BETWEEN 1 AND 5), sort_order INTEGER NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL DEFAULT 'ENABLED', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE question (id BIGSERIAL PRIMARY KEY, topic_id BIGINT NOT NULL REFERENCES topic(id), external_key VARCHAR(120) UNIQUE, title TEXT NOT NULL, question_type VARCHAR(32) NOT NULL, star_level SMALLINT NOT NULL CHECK (star_level BETWEEN 1 AND 5), difficulty VARCHAR(32) NOT NULL, frequency_level VARCHAR(32) NOT NULL, origin_type VARCHAR(32) NOT NULL DEFAULT 'BUILTIN', status VARCHAR(32) NOT NULL DEFAULT 'ENABLED', one_liner TEXT, plain_explanation TEXT, design_reason TEXT, common_mistakes TEXT, score_points TEXT, extra_json JSONB NOT NULL DEFAULT '{}'::jsonb, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE question_answer (id BIGSERIAL PRIMARY KEY, question_id BIGINT NOT NULL REFERENCES question(id) ON DELETE CASCADE, answer_type VARCHAR(32) NOT NULL, content TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(question_id, answer_type));
CREATE TABLE question_follow_up (id BIGSERIAL PRIMARY KEY, question_id BIGINT NOT NULL REFERENCES question(id) ON DELETE CASCADE, parent_follow_up_id BIGINT REFERENCES question_follow_up(id), title TEXT NOT NULL, reference_answer TEXT, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tag (id BIGSERIAL PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE question_tag (question_id BIGINT NOT NULL REFERENCES question(id) ON DELETE CASCADE, tag_id BIGINT NOT NULL REFERENCES tag(id) ON DELETE CASCADE, PRIMARY KEY(question_id, tag_id));
CREATE TABLE content_source (id BIGSERIAL PRIMARY KEY, source_type VARCHAR(32) NOT NULL, title VARCHAR(300), url TEXT, license_name VARCHAR(120), retrieved_at TIMESTAMPTZ, note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE content_relation (id BIGSERIAL PRIMARY KEY, source_type VARCHAR(32) NOT NULL, source_id BIGINT NOT NULL, relation_type VARCHAR(32) NOT NULL, target_type VARCHAR(32) NOT NULL, target_id BIGINT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
